<div class="right_col" role="main"><div class="d-flex justify-content-between mb-3"><h2>Application Form Builder</h2><form method="get"><select class="form-control" name="circular_id" onchange="this.form.submit()"><?php foreach($circularItems as $c): ?><option value="<?= $c->id ?>" <?= $circular&&$circular->id==$c->id?'selected':'' ?>><?= esc($c->title) ?></option><?php endforeach ?></select></form></div>
<?php if($circular): ?><div class="row"><div class="col-lg-5"><div class="card shadow-sm"><div class="card-header">Add or edit custom field</div><div class="card-body"><?= form_open('school/admission/form-builder/save',['id'=>'field-form']) ?><input type="hidden" name="circular_id" value="<?= $circular->id ?>"><input type="hidden" id="field-id" name="field_id"><div class="mb-2"><label>Label *</label><input id="field-label" class="form-control" name="label" required></div><div class="mb-2"><label>Field key</label><input id="field-key" class="form-control" name="field_key" placeholder="sibling_student_id"><small>Leave blank to generate from label.</small></div><div class="row"><div class="col-md-6 mb-2"><label>Type *</label><select id="field-type" class="form-control" name="field_type"><?php foreach(['text','textarea','number','date','dropdown','radio','checkbox','file'] as $t): ?><option value="<?= $t ?>"><?= ucfirst($t) ?></option><?php endforeach ?></select></div><div class="col-md-6 mb-2"><label>Required *</label><select id="field-required" class="form-control" name="is_required"><option value="0">No</option><option value="1">Yes</option></select></div></div><div class="mb-2"><label>Placeholder</label><input id="field-placeholder" class="form-control" name="placeholder"></div><div class="mb-2"><label>Options</label><textarea id="field-options" class="form-control" name="options" rows="4" placeholder="One option per line"></textarea></div><div class="row"><div class="col-md-6 mb-2"><label>Sort order</label><input id="field-order" type="number" class="form-control" name="sort_order" value="0"></div><div class="col-md-6 mb-2"><label>Status</label><select id="field-status" class="form-control" name="status"><option value="1">Active</option><option value="0">Disabled</option></select></div></div><button class="btn btn-primary">Save field</button><button type="button" class="btn btn-light" onclick="document.getElementById('field-form').reset();document.getElementById('field-id').value=''">Clear</button><?= form_close() ?></div></div></div>
<div class="col-lg-7"><div class="card shadow-sm"><div class="card-header"><?= esc($circular->title) ?> fields</div><div class="card-body table-responsive"><table class="table"><thead><tr><th>Order</th><th>Label</th><th>Type</th><th>Required</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($fields as $f): $opts=implode("\n",json_decode($f->options_json?:'[]',true)?:[]); ?><tr><td><?= $f->sort_order ?></td><td><?= esc($f->label) ?><br><code><?= esc($f->field_key) ?></code></td><td><?= esc($f->field_type) ?></td><td><?= $f->is_required?'Yes':'No' ?></td><td><?= $f->status?'Active':'Disabled' ?></td><td><button type="button" class="btn btn-sm btn-outline-primary" data-field='<?= esc(json_encode(['id'=>$f->id,'label'=>$f->label,'key'=>$f->field_key,'type'=>$f->field_type,'required'=>$f->is_required,'placeholder'=>$f->placeholder,'options'=>$opts,'order'=>$f->sort_order,'status'=>$f->status]),'attr') ?>' onclick="editField(this)">Edit</button><?= form_open('school/admission/form-builder/delete/'.$f->id,['class'=>'d-inline']) ?><button class="btn btn-sm btn-outline-danger" onclick="return confirm('Delete this field?')">Delete</button><?= form_close() ?></td></tr><?php endforeach ?><?php if(!$fields): ?><tr><td colspan="6" class="text-center text-muted">No custom fields yet. Default applicant fields remain available.</td></tr><?php endif ?></tbody></table></div></div></div></div><?php else: ?><div class="alert alert-info">Create an admission circular first.</div><?php endif ?></div>
<script>function editField(b){const f=JSON.parse(b.dataset.field);for(const [id,v] of Object.entries({'field-id':f.id,'field-label':f.label,'field-key':f.key,'field-type':f.type,'field-required':f.required,'field-placeholder':f.placeholder||'','field-options':f.options,'field-order':f.order,'field-status':f.status}))document.getElementById(id).value=v;window.scrollTo({top:0,behavior:'smooth'});}</script>
